DELIMITER $$
--
-- Procedimentos
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `RegistarVenda` (IN `p_codMaquina` INT, IN `p_idProduto` INT, IN `p_idMetodoPagamento` INT)   BEGIN
    DECLARE p_valorProduto DECIMAL(8,2);
    DECLARE p_stockAtual INT;
 
    SELECT valorUnidade, stock
    INTO p_valorProduto, p_stockAtual
    FROM maquinaProduto
    WHERE codMaquina = p_codMaquina AND idProduto = p_idProduto;
 
    IF p_valorProduto IS NULL THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'O produto não existe na máquina especificada.';
    ELSEIF p_stockAtual IS NULL OR p_stockAtual <= 0 THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'O produto está sem stock na máquina especificada.';
    ELSE

        VALUES (p_codMaquina, p_idProduto, p_valorProduto, NOW(), p_idMetodoPagamento);
 
        UPDATE maquinaProduto
        SET stock = stock - 1
        WHERE codMaquina = p_codMaquina AND idProduto = p_idProduto;
    END IF;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `TotalVendasPorMaquina` (IN `p_dataInicio` DATETIME, IN `p_dataFim` DATETIME)   BEGIN
    -- Retorna o total de vendas por máquina entre o intervalo de datas
    SELECT
        codMaquina AS CodigoMaquina,
        SUM(valor) AS ValorTotalVendas
    FROM
        venda
    WHERE
        dataHora BETWEEN p_dataInicio AND p_dataFim
    GROUP BY
        codMaquina
    ORDER BY
        CodigoMaquina;
END$$

DELIMITER ;

